            lower(btrim('Sri Govindaraja Swamy Temple')),
            lower(btrim('Sri Kapilatheertham Temple')),
            lower(btrim('Sri Kalyana Venkateswara Swamy Temple')),
            lower(btrim('ISKCON Tirupati')),
            lower(btrim('Natural Arch, Tirumala hills (Silathoranam)')),
            lower(btrim('Talakona Waterfall')),
            lower(btrim('Chandragiri Fort')),
            lower(btrim('Sri Venkateswara Zoological Park'))
   )
     and id not in (
            '596b875e-23d5-5458-95e6-1e60e9b0f2af'::uuid,
            '2b7ae75d-18d3-53b8-99d7-7db09267c860'::uuid,
            '53f276b4-549f-5f06-ad7d-fd7e20bf5e4e'::uuid,
            '4da554ae-e148-5498-b3b7-3aa45f0835d1'::uuid,
            '27c6e70b-673e-5c80-a3cf-4e8f530098d8'::uuid,
            '74b454ed-cb0a-5cd9-9510-1ef251de5a8a'::uuid,
            '9cbbed7e-b526-5167-ba53-30214cfe3c44'::uuid,
            '550f0ee2-d898-5f44-9897-9fd72310d77f'::uuid,
            '065ed977-26c1-5fa7-814a-b299f52672a1'::uuid,
            'f0034b71-18fd-51cc-be00-b26dc17cec72'::uuid,
            '7ca7b062-f601-55a9-832f-f3355aa8a80d'::uuid,
            '632a8627-baca-5d32-ab42-cf7328af8da1'::uuid,
            '23e44a85-1086-58df-8a58-928830569f04'::uuid,
            '7f2c91c5-35c7-57d8-9d7a-833b033a4ef1'::uuid,
            '544ffb45-63d2-582b-8272-155f032b4901'::uuid,
            '7a69de5b-7744-5fa6-b972-f3a7ebb4f0fb'::uuid
   );
  if v_name_dupes <> 0 then
