  end if;

  -- (e) no slug conflicts (places.slug is globally unique per migration-008).
  select count(*) into v_slug_dupes from public.places
   where slug in (
            'marasa-sarovar-premiere',
            'fortune-select-grand-ridge',
            'ramee-guestline-hotel',
            'ekante-bliss',
            'kalyan-residency',
            'minerva-grand-tirupati',
            'sri-venkateswara-swamy-temple',
            'sri-padmavathi-ammavari-temple',
            'sri-govindaraja-swamy-temple',
            'sri-kapilatheertham-temple',
            'sri-kalyana-venkateswara-swamy-temple',
            'iskcon-tirupati',
            'natural-arch-tirumala-hills-silathoranam',
            'talakona-waterfall',
            'chandragiri-fort',
            'sri-venkateswara-zoological-park'
   )
     and id not in (
            '596b875e-23d5-5458-95e6-1e60e9b0f2af'::uuid,
            '2b7ae75d-18d3-53b8-99d7-7db09267c860'::uuid,
            '53f276b4-549f-5f06-ad7d-fd7e20bf5e4e'::uuid,
            '4da554ae-e148-5498-b3b7-3aa45f0835d1'::uuid,
            '27c6e70b-673e-5c80-a3cf-4e8f530098d8'::uuid,
            '74b454ed-cb0a-5cd9-9510-1ef251de5a8a'::uuid,
            '9cbbed7e-b526-5167-ba53-30214cfe3c44'::uuid,
            '550f0ee2-d898-5f44-9897-9fd72310d77f'::uuid,
            '065ed977-26c1-5fa7-814a-b299f52672a1'::uuid,
            'f0034b71-18fd-51cc-be00-b26dc17cec72'::uuid,
            '7ca7b062-f601-55a9-832f-f3355aa8a80d'::uuid,
            '632a8627-baca-5d32-ab42-cf7328af8da1'::uuid,
            '23e44a85-1086-58df-8a58-928830569f04'::uuid,
            '7f2c91c5-35c7-57d8-9d7a-833b033a4ef1'::uuid,
            '544ffb45-63d2-582b-8272-155f032b4901'::uuid,
            '7a69de5b-7744-5fa6-b972-f3a7ebb4f0fb'::uuid
   );
  if v_slug_dupes <> 0 then
    raise exception 'PREFLIGHT FAIL: % row(s) already use this batch''s slugs (on other ids) — re-run the review.', v_slug_dupes;
  end if;
  raise notice 'PREFLIGHT OK: no name/slug conflicts with the 16 batch rows.';

  -- (f) held-out guard: the 3 evidence-weak hotels must be ABSENT (by id AND
  --     by name) — they stay out until their evidence issues are resolved.
  select count(*) into v_held_ids from public.places
   where id in (
            'dae6afc7-c8e2-5578-89cb-cdc82c22fd0b'::uuid,
            'd8179ce2-2ad4-53fc-b0f8-3d157df0e901'::uuid,
            'f9fedd50-9641-5e7d-9d05-6e8d14181ad2'::uuid
   );
  select count(*) into v_held_names from public.places
   where lower(btrim(name)) in (
            lower(btrim('Hotel Nivaara Tirupati')),
            lower(btrim('Hotel PLR Grand')),
            lower(btrim('Hotel Bhimas'))
   );
  if v_held_ids <> 0 or v_held_names <> 0 then
    raise exception 'PREFLIGHT FAIL: held-out hotel row(s) present in public.places (by id: %, by name: %) — these stay excluded until their evidence conflicts are resolved by review.', v_held_ids, v_held_names;
  end if;
  raise notice 'PREFLIGHT OK: all 3 held-out hotels absent (Nivaara / PLR Grand / Bhimas).';

  -- (g) marker hygiene: 'p4-research-import' must be unused when fresh and present on
  --     exactly the 16 batch rows when already applied.
  select count(*) into v_markers from public.places where source = 'p4-research-import';
