    'Ramee Guestline Hotel',
    null,                    -- description: not captured in the worksheet; NEVER invented
    '14/37 Karakambadi Rd, Mangalam, Tirupati, Andhra Pradesh 517507',
    'Mangalam',
    'Tirupati',
    v_dest_id,               -- resolved live active tirupati destination (exact-one guarded)
    null,                    -- latitude: coordinates are NEVER estimated (see header)
    null,                    -- longitude
    array['lodging', 'brand_chain']::text[],
    'p4-research-import',
    'https://rameehotels.com/ramee-guestline-hotel-tirupati',
